56|// One scene view: sub-pages, keys, buttons, progress, chapter jump.
57|// Sub-page moves stay in client state; scene moves push a new route.
58|export function ScenePage({
59|  view,
60|  views,
61|  bookId,
62|  textVersion,
63|  bookIndex,
64|  bookTotal,
65|  panels,
66|  nextChapter,
67|}: {
68|  view: SceneView;
69|  views: { sceneId: string; pages: number }[];
70|  bookId: string;
71|  textVersion: string;
72|  bookIndex: number;
73|  bookTotal: number;
74|  panels: ChapterPanel[];
75|  nextChapter: { ch: number; firstSceneId: string } | null;
