97|  const headingRef = useRef<HTMLHeadingElement>(null);
98|  const readColRef = useRef<HTMLDivElement | null>(null);
99|  const figEls = useRef(new Map<string, HTMLElement>());
100|  const kind = subPageKind(page, view.pages.length, cover, end);
101|  const sub = kind === "text" ? (view.pages[textPageAt(page, cover)] ?? view.pages[0]) : undefined;
102|  const textIndex = textPageAt(page, cover);
103|  const atStart = view.prevSceneId === null && page === 0;
104|  const atBookEnd = view.nextSceneId === null && page === lastPage;
105|
106|  useEffect(() => {
107|    setPref(loadImageStylePref());
108|  }, []);
109|
110|  // The end page marks the chapter finished, unlocking the panels.
111|  useEffect(() => {
112|    if (kind === "end") markChapterEndReached(view.ch);
113|  }, [kind, view.ch]);
114|
115|  function changePref(next: ImageStylePref) {
116|    setPref(next);
117|    saveImageStylePref(next);
118|  }
119|
120|  function requestPanels(opener: HTMLElement | null) {
121|    if (panelsUnlocked(view.ch)) {
122|      setPanelsOpen(true);
123|      return;
124|    }
125|    gateOpener.current = opener;
126|    setGateOpen(true);
127|  }
128|
129|  function showAnyway() {
130|    markPanelsShownAnyway(view.ch);
131|    setGateOpen(false);
132|    setPanelsOpen(true);
133|  }
134|
135|  function notYet() {
136|    setGateOpen(false);
137|    gateOpener.current?.focus?.();
138|    gateOpener.current = null;
139|  }
140|
141|  function readFirst() {
142|    markChapterSetAside(view.ch);
143|    setOfferAside(true);
144|  }
145|
146|  function goNextChapter() {
147|    if (!nextChapter) return;
148|    hasNavigated = true;
149|    router.push(`/leer/${nextChapter.firstSceneId}`);
150|  }
151|
152|  const figsByN = useMemo(() => groupFiguresByEndN(pic.figures), [pic.figures]);
153|
154|  function gotoFigure(fig: InlineFigure) {
155|    const at = pageOfOrdinal(view.pages, fig.endN);
156|    if (at < 0) return;
157|    setPage(at + (cover ? 1 : 0));
158|    readColRef.current?.scrollTo(0, 0);
159|    requestAnimationFrame(() => {
160|      requestAnimationFrame(() => {
161|        const el = figEls.current.get(fig.id) ?? null;
162|        el?.scrollIntoView({ block: "nearest" });
163|        pulse(el);
164|      });
165|    });
166|  }
167|
168|  function gotoScenePicture() {
