175|  function move(action: NavAction) {
176|    pic.hidePopover();
177|    const next = navReducer({ sceneId: view.sceneId, page }, action, index);
178|    if (next.sceneId !== view.sceneId) {
179|      hasNavigated = true;
180|      if (next.page > 0) enterAtEnd = true;
181|      router.push(`/leer/${next.sceneId}`);
