187|    }
188|  }
189|
190|  function goNext() {
191|    move({ kind: "next" });
192|  }
193|
194|  function goPrev() {
195|    move({ kind: "prev" });
196|  }
197|
198|  // Scene entry resets orientation; sub-page moves keep the heading.
199|  useEffect(() => {
200|    if (hasNavigated) headingRef.current?.focus();
201|    readColRef.current?.scrollTo(0, 0);
202|  }, [view.sceneId]);
203|
204|  useEffect(() => {
205|    const onKey = (event: KeyboardEvent) => {
206|      if (event.metaKey || event.ctrlKey || event.altKey) return;
207|      const target = event.target as HTMLElement | null;
208|      if (
209|        target &&
210|        (target.tagName === "INPUT" ||
211|          target.tagName === "SELECT" ||
212|          target.tagName === "TEXTAREA" ||
213|          target.isContentEditable)
