220|      } else if (event.key === "ArrowLeft") {
221|        event.preventDefault();
222|        goPrev();
223|      }
224|    };
225|    window.addEventListener("keydown", onKey);
226|    return () => window.removeEventListener("keydown", onKey);
227|  }, [page, view.sceneId, index, router]);
