249|            <p className="cover-num" data-long={coverLong} aria-label={`Chapter ${view.ch}`}>
250|              {view.ch}
251|            </p>
252|            <h1
253|              className="chapter-title cover-title"
254|              data-long={coverLong}
255|              id="scene-heading"
256|              ref={headingRef}
257|              tabIndex={-1}
258|            >
259|              {view.chapterTitle}
260|            </h1>
261|            <hr className="cover-rule" />
262|            {offerAside ? (
263|              <PanelsQuietLink onOpen={requestPanels} />
264|            ) : (
265|              <PanelsOfferCard panels={panels} onShowAnyway={showAnyway} onReadFirst={readFirst} />
266|            )}
267|            <button type="button" className="cover-begin" onClick={goNext}>
268|              Begin the chapter →
269|            </button>
270|          </>
271|        ) : kind === "end" ? (
272|          <>
273|            <div className="kicker">End of Chapter {view.ch}</div>
274|            <div className="end-card">
275|              <BlurredThumbs panels={panels} unblurredCount={Math.min(4, panels.length)} />
276|              <h2>Relive this chapter in panels</h2>
277|              <div className="panels-btns">
278|                <button type="button" className="panels-primary" onClick={() => setPanelsOpen(true)}>
279|                  Open the panels
280|                </button>
281|              </div>
282|            </div>
283|            {nextChapter ? (
284|              <button type="button" className="end-next" onClick={goNextChapter}>
285|                On to Chapter {nextChapter.ch} →
286|              </button>
287|            ) : (
288|              <p className="the-end">The end.</p>
289|            )}
290|          </>
291|        ) : (
292|          <>
293|            <div className="kicker">Chapter {view.ch}</div>
294|            <h1 className="chapter-title" id="scene-heading" ref={headingRef} tabIndex={-1}>
295|              {view.chapterTitle}
296|            </h1>
297|            <div className="scene-line">
298|              <span>
299|                Scene {view.k} of {view.n}
300|                {view.pages.length > 1 ? ` · Page ${textIndex + 1} of ${view.pages.length}` : ""}
301|              </span>
302|            </div>
303|            <div className={`body-text${textIndex === 0 ? " dropcap" : ""}`} ref={pic.viewRef}>
304|              {sub?.paragraphs.map((p, i, arr) => (
305|                <Fragment key={p.id}>
306|                  <p id={p.id} data-n={p.n} data-cont={p.cont ? true : undefined}>
307|                    {p.text}
308|                  </p>
309|                  {/* A figure for n lands after its last visible fragment. */}
310|                  {figuresAfter(arr, i, figsByN).map((fig) => (
311|                    <InlineFigureView
312|                      key={fig.id}
313|                      figure={fig}
314|                      onRemove={() => pic.removeFigure(fig.id)}
315|                      onRetry={() => pic.retryFigure(fig.id)}
316|                      onOpen={pic.lightbox.open}
317|                      refCb={(el) => {
318|                        if (el) figEls.current.set(fig.id, el);
319|                        else figEls.current.delete(fig.id);
320|                      }}
321|                    />
322|                  ))}
323|                </Fragment>
324|              ))}
325|              {pic.popover !== null ? (
326|                <SelectionPopover
327|                  pos={pic.popover}
328|                  popRef={pic.popRef}
329|                  onPick={() => pic.illustratePassage()}
330|                />
331|              ) : null}
332|            </div>
333|          </>
334|        )}
335|      </div>
336|      <PictureVault
337|        scene={pic.card.phase === "ready" ? { url: pic.card.url, caption: pic.card.caption } : null}
338|        figures={pic.figures}
339|        onGotoScene={gotoScenePicture}
340|        onGotoFigure={gotoFigure}
341|        onOpen={pic.lightbox.open}
342|        pref={pref}
343|        onPrefChange={changePref}
344|      />
345|      <BandPager
346|        k={view.k}
347|        n={view.n}
348|        bookIndex={bookIndex}
349|        bookTotal={bookTotal}
350|        onPrev={goPrev}
351|        onNext={goNext}
352|        atStart={atStart}
353|        atBookEnd={atBookEnd}
354|      />
355|      <Lightbox item={pic.lightbox.item} onClose={pic.lightbox.close} />
356|      {gateOpen ? <SpoilerGateDialog onShow={showAnyway} onNotYet={notYet} /> : null}
357|      {panelsOpen ? (
358|        <PanelsModal
359|          ch={view.ch}
360|          chapterTitle={view.chapterTitle}
361|          panels={panels}
362|          onClose={() => setPanelsOpen(false)}
363|          onOpenArt={pic.lightbox.open}
364|        />
365|      ) : null}
366|    </>
367|  );
368|}

