1|// Reader model: the slim shape the client receives. Joins paragraphs to
2|// scenes by ordinal range in reading order; analysis internals never leave.
3|import type { AnalyzedScene, Book } from "./types";
4|import type { Vector8 } from "./types";
5|
6|export interface ReaderParagraph {
7|  id: string;
8|  n: number;
9|  text: string;
10|  // Set on fragments after the first when paginateScene splits one
11|  // paragraph across pages. Fragments share n; ids stay unique.
12|  cont?: boolean;
13|}
14|
15|export interface ReaderScene {
16|  id: string;
17|  title: string;
18|  emotion: { vector: Vector8; intensity: number; tempo: number } | null;
19|  paragraphs: ReaderParagraph[];
20|}
21|
22|export interface ReaderChapter {
23|  ch: number;
24|  title: string;
25|  scenes: ReaderScene[];
26|}
27|
28|export interface ReaderModel {
29|  bookId: string;
30|  textVersion: string;
31|  title: string;
32|  author: string;
33|  chapters: ReaderChapter[];
34|}
35|
36|// 1280x800 fit: the reading column is 595 px tall and the heading block
37|// (kicker, title, Scene/Page line) takes ~115 px of it on every page,
38|// leaving ~480 px for text. At 20.5px/1.7 each line costs 34.85 px, so a
39|// page holds 13 lines; the ~538 px measure fits ~58 chars per line, so
40|// each paragraph costs ceil((chars + indent) / 58) lines and short
41|// dialogue lines each take a full line. Page one also carries the drop cap, so it
42|// budgets one less. Paragraphs stay whole; one over budget takes its own
43|// page.
44|export const PAGE_WORD_BUDGET = 250;
45|const READ_COL_PX = 595;
46|const HEADING_PX = 115;
47|const LINE_PX = 20.5 * 1.7;
48|export const CHARS_PER_LINE = 58;
49|// First-line indent (1.5em ≈ 30 px ≈ 4 chars) eats measure on every
50|// indented paragraph: all but the scene opener and cont fragments.
51|export const INDENT_CHARS = 4;
52|export const LINES_PER_PAGE = Math.floor((READ_COL_PX - HEADING_PX) / LINE_PX);
53|export const FIRST_PAGE_LINES = LINES_PER_PAGE - 1;
54|
55|export interface SubPage {
56|  paragraphs: ReaderParagraph[];
57|  startN: number;
58|  endN: number;
59|  words: number;
60|}
61|
62|export function countWords(text: string): number {
63|  const words = text.split(/\s+/).filter((w) => w.length > 0);
64|  return words.length;
65|}
66|
67|export function estimateLines(text: string, indented = false): number {
68|  return Math.max(1, Math.ceil((text.length + (indented ? INDENT_CHARS : 0)) / CHARS_PER_LINE));
69|}
70|
71|// Title measure: ~26 chars per line at the 44 px chapter-title size in
72|// the 538 px column. "The Cyclone" is 1 line,
73|// "The Discovery of Oz, the Terrible" is 2.
74|export const TITLE_CHARS_PER_LINE = 26;
75|const WRAPPED_TITLE_PENALTY = 2;
76|
77|export function chapterTitleLines(title: string): number {
78|  if (title.length === 0) return 1;
79|  return Math.max(1, Math.ceil(title.length / TITLE_CHARS_PER_LINE));
80|}
81|
82|// Latest sentence end (`. `, `! `, `? `, `; `, closing quotes included)
83|// at or before maxChars, as a cut index into text, or -1 when none fits.
84|// The cut sits just past the space, so fragments join back exactly.
85|function sentenceCut(text: string, maxChars: number): number {
86|  const re = /[.!?;]["'”’)\]]* /g;
87|  let cut = -1;
88|  for (;;) {
89|    const m = re.exec(text);
90|    if (m === null) break;
91|    const end = m.index + m[0].length;
92|    if (end > maxChars || end >= text.length) break;
93|    cut = end;
94|  }
95|  return cut;
96|}
97|
98|// Latest cut at or before maxChars that fits maxWords: the sentence cut
99|// when one fits, else the last space, else a hard cut. Backs off to an
100|// earlier space while the prefix holds too many words.
101|function findCut(text: string, maxChars: number, maxWords: number): number {
102|  const cap = Math.min(maxChars, text.length - 1);
103|  let cut = sentenceCut(text, cap);
104|  if (cut <= 0) {
105|    const at = text.lastIndexOf(" ", cap);
106|    // at + 1 can pass maxChars by one char (a 2-line 59-char slip
107|    // into a 1-line slot), so clamp: the space opens the next fragment.
108|    cut = at <= 0 ? cap : Math.min(at + 1, cap);
109|  }
110|  while (cut > 1 && countWords(text.slice(0, cut)) > maxWords) {
111|    const at = text.lastIndexOf(" ", cut - 2);
112|    if (at <= 0) break;
113|    cut = at + 1;
114|  }
115|  return Math.max(1, Math.min(cut, text.length - 1));
116|}
117|
118|// Split one scene into sub-pages: a page closes when the next paragraph
119|// would pass the word budget or the line budget. A paragraph that fits
120|// the remaining budget, or a fresh page when the current one has text,
121|// moves whole. One longer than a full page fills the current page at a
122|// sentence boundary (word boundary fallback) and continues on the next;
123|// fragments share n, later ones carry cont. A wrapped chapter title
124|// costs every page WRAPPED_TITLE_PENALTY lines.
125|export function paginateScene(
126|  paragraphs: ReaderParagraph[],
127|  budgetWords: number = PAGE_WORD_BUDGET,
128|  chapterTitle: string = "",
129|): SubPage[] {
130|  const penalty = chapterTitleLines(chapterTitle) > 1 ? WRAPPED_TITLE_PENALTY : 0;
131|  const budgetFor = (pageIndex: number): number =>
132|    (pageIndex === 0 ? FIRST_PAGE_LINES : LINES_PER_PAGE) - penalty;
133|  const pages: SubPage[] = [];
134|  let current: ReaderParagraph[] = [];
135|  let words = 0;
136|  let lines = 0;
137|  const flush = () => {
138|    if (current.length === 0) return;
139|    pages.push({
140|      paragraphs: current,
141|      startN: current[0]?.n ?? 0,
142|      endN: current[current.length - 1]?.n ?? 0,
143|      words,
144|    });
145|    current = [];
146|    words = 0;
147|    lines = 0;
148|  };
149|  const pushFrag = (p: ReaderParagraph, text: string, fragNo: number, indented: boolean) => {
150|    const w = countWords(text);
151|    const l = estimateLines(text, indented);
152|    current.push(
153|      fragNo === 0 ? { id: p.id, n: p.n, text } : { id: `${p.id}~${fragNo + 1}`, n: p.n, text, cont: true },
154|    );
155|    words += w;
156|    lines += l;
157|  };
158|  for (let pi = 0; pi < paragraphs.length; pi++) {
159|    const p = paragraphs[pi] as ReaderParagraph;
160|    let rest = p.text;
161|    let fragNo = 0;
162|    while (rest.length > 0) {
163|      // The scene opener carries the drop cap and cont fragments carry
164|      // no indent; every other first fragment pays INDENT_CHARS.
165|      const indented = pi > 0 && fragNo === 0;
166|      const budget = budgetFor(pages.length);
167|      const remainingLines = budget - lines;
168|      const remainingWords = budgetWords - words;
169|      const wRest = countWords(rest);
170|      const lRest = estimateLines(rest, indented);
171|      if (lRest <= remainingLines && wRest <= remainingWords) {
172|        pushFrag(p, rest, fragNo, indented);
173|        rest = "";
174|      } else if (remainingLines <= 0 || remainingWords <= 0) {
175|        flush();
176|      } else if (current.length > 0 && lRest <= budgetFor(pages.length + 1) && wRest <= budgetWords) {
177|        flush();
178|      } else {
179|        const cut = findCut(rest, remainingLines * CHARS_PER_LINE - (indented ? INDENT_CHARS : 0), remainingWords);
180|        pushFrag(p, rest.slice(0, cut), fragNo, indented);
181|        fragNo += 1;
182|        rest = rest.slice(cut);
183|        flush();
184|      }
185|    }
186|  }
187|  flush();
188|  if (pages.length === 0) pages.push({ paragraphs: [], startN: 0, endN: 0, words: 0 });
189|  return pages;
190|}
