207|// The chapter cover (page 0 of the first scene) and the chapter-end
208|// page (trailing page of the last scene) belong to their scene: they
209|// shift sub-page indexes only, so music entry still fires per route id.
210|export type SubPageKind = "cover" | "text" | "end";
211|
212|export function subPageCount(textPages: number, cover: boolean, end: boolean): number {
213|  return textPages + (cover ? 1 : 0) + (end ? 1 : 0);
