231|export function panelCaption(summary: string): string {
232|  const clean = summary.replace(/\s+/g, " ").trim();
233|  if (clean.length <= PANEL_CAPTION_MAX) return clean;
234|  const end = clean.search(/[.!?;]["'”’)\]]?\s/);
235|  const first = end > 0 && end < PANEL_CAPTION_MAX ? clean.slice(0, end + 1) : null;
236|  if (first) return first;
