250|  if (at < 0 || !flat[at]) throw new Error(`unknown scene ${sceneId}`);
251|  const entry = flat[at] as { ch: number; chapterTitle: string; scene: ReaderScene };
252|  const chapterScenes = flat.filter((e) => e.ch === entry.ch);
253|  const atInChapter = chapterScenes.findIndex((e) => e.scene.id === sceneId);
254|  const prev = at > 0 ? flat[at - 1] : null;
255|  const next = at < flat.length - 1 ? flat[at + 1] : null;
256|  return {
257|    sceneId,
258|    ch: entry.ch,
259|    chapterTitle: entry.chapterTitle,
260|    title: entry.scene.title,
261|    emotion: entry.scene.emotion,
262|    pages: paginateScene(entry.scene.paragraphs, budgetWords, entry.chapterTitle),
263|    prevSceneId: prev?.scene.id ?? null,
264|    nextSceneId: next?.scene.id ?? null,
265|    k: atInChapter + 1,
