272|export interface NavState {
273|  sceneId: string;
274|  page: number;
275|}
276|
277|export type NavAction =
278|  | { kind: "next" }
279|  | { kind: "prev" }
280|  | { kind: "goto"; sceneId: string; atEnd?: boolean };
281|
282|export interface NavIndex {
283|  order: string[];
284|  pageCounts: Map<string, number>;
285|}
286|
287|export function buildNavIndex(views: { sceneId: string; pages: number }[]): NavIndex {
288|  return {
289|    order: views.map((v) => v.sceneId),
290|    pageCounts: new Map(views.map((v) => [v.sceneId, v.pages] as [string, number])),
291|  };
292|}
293|
294|// Every pager move in one place: next/prev cross scenes and chapters,
295|// going back lands on the last sub-page, bounds are no-ops, unknown
296|// goto ids keep state.
297|export function navReducer(state: NavState, action: NavAction, index: NavIndex): NavState {
298|  const at = index.order.indexOf(state.sceneId);
299|  if (at < 0) return state;
300|  const pages = index.pageCounts.get(state.sceneId) ?? 1;
301|  if (action.kind === "next") {
302|    if (state.page < pages - 1) return { ...state, page: state.page + 1 };
303|    const nextId = index.order[at + 1];
304|    return nextId === undefined ? state : { sceneId: nextId, page: 0 };
305|  }
306|  if (action.kind === "prev") {
307|    if (state.page > 0) return { ...state, page: state.page - 1 };
308|    const prevId = at > 0 ? index.order[at - 1] : undefined;
309|    if (prevId === undefined) return state;
310|    return { sceneId: prevId, page: (index.pageCounts.get(prevId) ?? 1) - 1 };
311|  }
312|  if (index.order.indexOf(action.sceneId) < 0) return state;
313|  const count = index.pageCounts.get(action.sceneId) ?? 1;
314|  return { sceneId: action.sceneId, page: action.atEnd ? count - 1 : 0 };
315|}
316|
317|// True only when the scene id changed. The container gates observeScene
318|// on this, so sub-page moves never touch the scheduler.
319|export function isSceneEntry(prevSceneId: string | null, nextSceneId: string): boolean {
320|  return prevSceneId !== nextSceneId;
321|}
322|
323|export interface SceneEntryGate {
324|  observedId: string | null;
325|  routeId: string | null;
326|  manifestReady: boolean;
327|}
328|
329|// The container's effect gate in one testable place: observe exactly once
330|// per route id, only after the manifest lands. Route params can lag a
331|// render, so the last observed id is compared before every observe call.
332|export function nextSceneEntry(gate: SceneEntryGate): {
333|  shouldObserve: boolean;
334|  nextObservedId: string | null;
335|} {
336|  if (!gate.routeId || !gate.manifestReady || !isSceneEntry(gate.observedId, gate.routeId)) {
337|    return { shouldObserve: false, nextObservedId: gate.observedId };
338|  }
339|  return { shouldObserve: true, nextObservedId: gate.routeId };
340|}
341|
342|// Throws on unordered scenes and on paragraphs covered zero or two times.
343|export function buildReaderModel(
344|  book: Pick<Book, "id" | "title" | "author" | "chapters" | "paragraphs" | "textVersion">,
345|  analysis: { scenes: AnalyzedScene[] },
346|): ReaderModel {
347|  const byN = new Map(book.paragraphs.map((p) => [p.n, p]));
348|  const scenes = [...analysis.scenes];
349|  for (let i = 1; i < scenes.length; i++) {
350|    const prev = scenes[i - 1];
351|    const cur = scenes[i];
352|    if (prev && cur && (cur.start_n < prev.start_n || (cur.start_n === prev.start_n && cur.end_n < prev.end_n))) {
353|      throw new Error(`scenes out of order at ${cur.id}`);
354|    }
355|  }
356|  const seen = new Set<number>();
357|  const sceneParagraphs = new Map<string, ReaderParagraph[]>();
358|  for (const scene of scenes) {
359|    const paras: ReaderParagraph[] = [];
360|    for (let n = scene.start_n; n <= scene.end_n; n++) {
361|      const p = byN.get(n);
362|      if (!p) throw new Error(`scene ${scene.id} covers missing ordinal ${n}`);
363|      if (seen.has(n)) throw new Error(`ordinal ${n} covered twice`);
364|      seen.add(n);
365|      paras.push({ id: p.id, n: p.n, text: p.text });
366|    }
367|    sceneParagraphs.set(scene.id, paras);
368|  }
369|  if (seen.size !== book.paragraphs.length) {
370|    throw new Error(`coverage gap: ${book.paragraphs.length - seen.size} paragraphs uncovered`);
371|  }
372|  const chapters: ReaderChapter[] = book.chapters.map((chapter) => {
373|    const mine = scenes.filter((s) => s.ch === chapter.ch);
374|    if (mine.some((s) => s.start_n < chapter.start_n || s.end_n > chapter.end_n)) {
375|      throw new Error(`a scene crosses chapter ${chapter.ch} bounds`);
376|    }
377|    return {
378|      ch: chapter.ch,
379|      title: chapter.title,
380|      scenes: mine.map((s) => ({
381|        id: s.id,
382|        title: s.title,
383|        emotion: s.final === null ? null : { ...s.final },
384|        paragraphs: sceneParagraphs.get(s.id) ?? [],
385|      })),
386|    };
387|  });
388|  return {
389|    bookId: book.id,
390|    textVersion: book.textVersion,
391|    title: book.title,
392|    author: book.author,
393|    chapters,
394|  };
