101|function stagedPaths() {
102|  const output = execFileSync(
103|    'git',
104|    ['diff', '--cached', '--name-only', '--diff-filter=ACMR', '-z'],
105|    { encoding: 'buffer', stdio: ['ignore', 'pipe', 'ignore'] },
106|  );
107|  const text = output.toString('utf8');
108|  return text.length === 0 ? [] : text.split('\0').filter((entry) => entry !== '');
109|}
110|
111|// Pure and testable: flags from `git diff --numstat -z` output. Each record is
112|// one NUL-terminated "added\tdeleted\tpath" chunk; a rename is a chunk with
113|// an empty path followed by old-name and new-name chunks, keyed on the new.
114|export function parseNumstatZ(text) {
115|  const flags = new Map();
116|  if (text.length === 0) return flags;
117|  const parts = text.split('\0');
118|  for (let i = 0; i < parts.length; i++) {
119|    const chunk = parts[i];
120|    if (chunk === '') continue;
121|    const record = /^(\d+|-)\t(\d+|-)\t([\s\S]*)$/.exec(chunk);
122|    if (!record) continue;
123|    const isBinary = record[1] === '-' && record[2] === '-';
124|    let path = record[3];
125|    if (path === '') {
126|      const renamed = parts[i + 2];
127|      i += 2;
128|      if (renamed === undefined || renamed === '') continue;
129|      path = renamed;
130|    }
131|    flags.set(path, isBinary);
132|  }
133|  return flags;
134|}
135|
136|// Binary flags from git's own numstat: git prints "-\t-\t" for files whose
137|// first 8000 bytes hold a NUL byte, so this reuses that detection.
138|function stagedBinaryFlags() {
139|  const output = execFileSync(
140|    'git',
141|    ['diff', '--cached', '--numstat', '--diff-filter=ACMR', '-z'],
142|    { encoding: 'buffer', stdio: ['ignore', 'pipe', 'ignore'] },
143|  );
144|  return parseNumstatZ(output.toString('utf8'));
145|}
146|
147|function stagedBlobSize(path) {
148|  const output = execFileSync('git', ['cat-file', '-s', ':' + path], {
149|    encoding: 'utf8',
150|    stdio: ['ignore', 'pipe', 'ignore'],
151|  });
152|  return Number.parseInt(output.trim(), 10);
153|}
154|
155|function main() {
156|  let paths;
157|  let binaryFlags = new Map();
158|  try {
159|    paths = stagedPaths();
160|    binaryFlags = stagedBinaryFlags();
161|  } catch {
162|    console.error('warning: not a git repo, skipping the file-size check');
163|    return 0;
164|  }
165|  const entries = [];
166|  for (const path of paths) {
167|    if (isIgnored(path)) continue;
168|    let bytes;
169|    try {
170|      bytes = stagedBlobSize(path);
171|    } catch {
172|      continue; // Left the index since the diff was read.
173|    }
174|    entries.push({ path, bytes, isBinary: binaryFlags.get(path) === true });
175|  }
176|  const oversized = findOversized(entries);
177|  if (oversized.length === 0) return 0;
178|  console.error(`error: ${oversized.length} staged file(s) over the ${MAX_TOKENS}-token limit (tokens = ceil(bytes/4)):`);
179|  for (const file of oversized) {
180|    console.error(`  ${file.path}: ${file.bytes} bytes, about ${file.tokens} tokens`);
181|  }
182|  console.error('');
183|  console.error(SPLIT_HELP);
184|  return 1;
185|}
